//! `bob-wiregen` — render the TypeScript wire module from the engine's
//! normative wire schema (A-10 / AT-S5-03).
//!
//! ```text
//! bob-wiregen --out shell/src/protocol.ts     # write the committed artifact
//! bob-wiregen --check --out shell/src/protocol.ts
//! bob-wiregen                                  # print to stdout
//! ```
//!
//! `--check` compares the regenerated bytes with the file on disk and exits 1
//! when it is stale, so CI (`npm run check:protocol`) and `cargo test` (which
//! calls [`bob_engine::tsgen::generate`] directly) enforce the same invariant:
//! the committed TS module is exactly what the engine's wire model produces.
//!
//! Line endings are compared after normalizing CRLF to LF: this repository
//! stores text as LF with `core.autocrlf=true` on Windows, so a checkout may
//! materialize CRLF. That is a git eol policy, not wire drift.

use std::io::Write;
use std::path::PathBuf;
use std::process::ExitCode;

use bob_engine::tsgen;

const USAGE: &str = "usage: bob-wiregen [--check] [--out <path>]\n\
                     \x20 --out <path>  target file (default: <repo>/shell/src/protocol.ts)\n\
                     \x20 --check       exit 1 if the target differs from the generated bytes\n\
                     \x20 (no args)     print the generated module to stdout";

fn main() -> ExitCode {
    let mut out: Option<PathBuf> = None;
    let mut check = false;
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--out" | "-o" => match args.next() {
                Some(p) => out = Some(PathBuf::from(p)),
                None => {
                    eprintln!("bob-wiregen: --out needs a path\n{USAGE}");
                    return ExitCode::from(2);
                }
            },
            "--check" => check = true,
            "--help" | "-h" => {
                println!("{USAGE}");
                return ExitCode::SUCCESS;
            }
            other => {
                eprintln!("bob-wiregen: unknown argument '{other}'\n{USAGE}");
                return ExitCode::from(2);
            }
        }
    }

    let generated = tsgen::generate();
    let to_stdout = out.is_none();
    let target = out.unwrap_or_else(tsgen::generated_path);

    if check {
        let committed = match std::fs::read_to_string(&target) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("bob-wiregen: cannot read {}: {e}", target.display());
                return ExitCode::from(1);
            }
        };
        if tsgen::normalize_newlines(&committed) == tsgen::normalize_newlines(&generated) {
            println!(
                "bob-wiregen: {} is up to date ({} bytes)",
                target.display(),
                generated.len()
            );
            ExitCode::SUCCESS
        } else {
            eprintln!(
                "bob-wiregen: {} is STALE — it is not what the engine's wire schema produces.",
                target.display()
            );
            eprintln!("bob-wiregen: regenerate it (shell/): npm run gen:protocol");
            ExitCode::from(1)
        }
    } else if to_stdout {
        print!("{generated}");
        ExitCode::SUCCESS
    } else {
        if let Some(dir) = target.parent() {
            if !dir.as_os_str().is_empty() {
                if let Err(e) = std::fs::create_dir_all(dir) {
                    eprintln!("bob-wiregen: cannot create {}: {e}", dir.display());
                    return ExitCode::from(1);
                }
            }
        }
        match std::fs::File::create(&target) {
            Ok(mut f) => {
                if let Err(e) = f.write_all(generated.as_bytes()) {
                    eprintln!("bob-wiregen: cannot write {}: {e}", target.display());
                    return ExitCode::from(1);
                }
                println!(
                    "bob-wiregen: wrote {} ({} bytes, schema {})",
                    target.display(),
                    generated.len(),
                    bob_engine::protocol::schema_hash()
                );
                ExitCode::SUCCESS
            }
            Err(e) => {
                eprintln!("bob-wiregen: cannot create {}: {e}", target.display());
                ExitCode::from(1)
            }
        }
    }
}
